function toast(msg,ms=1700){let e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(APP.toastTimer);APP.toastTimer=setTimeout(()=>e.classList.remove('show'),ms)}
function romKey(bytes,f){return `${bytes.length}-${f.stored}-${f.developer}-${f.gameId}`}
function formatBytes(n){return n>=1048576?(n/1048576).toFixed(n>=10485760?0:1)+' MiB':n>=1024?Math.round(n/1024)+' KiB':n+' B'} function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
