async function deleteLibraryRom(key){await DB.del('rom:'+key);let lib=await DB.get('romLibrary')||[];lib=lib.filter(x=>x.key!==key);await DB.set('romLibrary',lib);if(await DB.get('lastRomKey')===key)await DB.del('lastRomKey');renderLibrary();toast('ROM eliminada')}
async function clearLibrary(){if(typeof confirm==='function'&&!confirm('¿Vaciar la biblioteca de ROMs guardadas? Los saves y estados no se borrarán.'))return;let lib=await DB.get('romLibrary')||[];for(let x of lib)await DB.del('rom:'+x.key);await DB.set('romLibrary',[]);await DB.del('lastRomKey');await DB.del('lastRom');renderLibrary();toast('Biblioteca vaciada')}
function stateKey(slot){return `state:${APP.romKey}:${slot}`}
function autoKey(){return `auto:${APP.romKey}`}
