function exportInternalEeprom(){if(!APP.rom)return;let u=APP.core.eeprom.internal.slice(),name=(APP.romName.replace(/\.[^.]+$/,'')||'WonderSwan')+'.ieeprom';downloadBytes(u,name);toast(`EEPROM interna ${u.length} B exportada`)}
async function importBattery(file){if(!file||!APP.rom)return;let u=new Uint8Array(await file.arrayBuffer()),n=(file.name||'').toLowerCase(),c=APP.core,ok=false,msg='';
 if(n.endsWith('.ieeprom')){if(u.length!==c.eeprom.internal.length)throw Error(`.ieeprom: se esperaban ${c.eeprom.internal.length} B`);c.eeprom.internal.set(u);let type=c.bus.color?'wsc':'ws',rec=APP.firmware[type];if(rec){rec={...rec,eeprom:u.slice().buffer,time:Date.now()};APP.firmware[type]=rec;try{await DB.set('firmware:'+type,rec)}catch(_){}}ok=true;msg='EEPROM interna Mesen importada'}
 else if(n.endsWith('.eeprom')||n.endsWith('.eep')){if(c.bus.saveKind!=='eeprom'||!c.eeprom.externalSize)throw Error('El cartucho actual no usa EEPROM externa');if(u.length!==c.eeprom.externalSize)throw Error(`.eeprom: se esperaban ${c.eeprom.externalSize} B`);c.eeprom.external.set(u);c.saveDirty=true;await persistBattery(true);ok=true;msg='EEPROM de cartucho importada'}
 else if(n.endsWith('.sav')){if(c.bus.saveKind!=='sram'||!c.bus.saveBytes)throw Error('El cartucho actual no usa SRAM');if(u.length!==c.bus.saveBytes)throw Error(`.sav: se esperaban ${c.bus.saveBytes} B`);c.loadSaveData(u);c.saveDirty=true;await persistBattery(true);ok=true;msg='SRAM Mesen importada'}
 else {if(c.bus.saveBytes&&u.length===c.bus.saveBytes){c.loadSaveData(u);c.saveDirty=true;await persistBattery(true);ok=true;msg='Save de cartucho importado'}else if(u.length===c.eeprom.internal.length){c.eeprom.internal.set(u);ok=true;msg='EEPROM interna importada'}else throw Error('Tamaño de save no reconocido')}
 if(ok)toast(msg+' ✓');$('#batteryFile').value=''}
async function requestWakeLock(){if(!APP.settings.wakeLock||!APP.rom||!APP.core.running||document.hidden||!navigator.wakeLock)return;try{if(!APP.wake){APP.wake=await navigator.wakeLock.request('screen');APP.wake.addEventListener('release',()=>{APP.wake=null;updateWakeText()})}}catch(_){APP.wake=null}updateWakeText()}
async function releaseWakeLock(){try{if(APP.wake)await APP.wake.release()}catch(_){}APP.wake=null;updateWakeText()}
function updateWakeText(){let e=$('#wakeStatus');if(!e)return;e.textContent=APP.wake?'Pantalla mantenida activa':navigator.wakeLock?'Pantalla activa normal':'Wake Lock no disponible'}
function updateWakeLock(){APP.settings.wakeLock&&APP.core.running&&!document.hidden?requestWakeLock():releaseWakeLock()}
function pokeToolbar(){clearTimeout(APP.toolbarTimer);document.body.classList.remove('toolbar-hidden');$('#toolbarReveal').classList.add('hidden');if(APP.settings.autoHideToolbar&&effectiveLayout()==='landscape'&&APP.core.running&&!$('#sheetBackdrop').classList.contains('open'))APP.toolbarTimer=setTimeout(()=>{document.body.classList.add('toolbar-hidden');$('#toolbarReveal').classList.remove('hidden')},2600)}
function selectSlot(slot){APP.stateSlot=Math.max(1,Math.min(4,+slot));storeSettings();updateSlotUI();refreshStateSlots()}
function updateGamepadStatus(name=''){APP.gamepadName=name;$('#gamepadStatus').textContent=name?`Conectado: ${name.slice(0,34)}`:'Sin gamepad';$('#gamepadDot').classList.toggle('on',!!name);$('#gamepadPill').classList.toggle('hidden',!name)}
function pressedButton(g,i){return !!(g.buttons[i]&&(g.buttons[i].pressed||g.buttons[i].value>.55))}
function pollGamepad(){if(!APP.settings.gamepad||!navigator.getGamepads){INPUT.clear('gamepad');updateGamepadStatus('');return}let g=[...navigator.getGamepads()].find(Boolean);if(!g){INPUT.clear('gamepad');if(APP.gamepadName)updateGamepadStatus('');return}let n=new Set,ax=g.axes||[],x0=ax[0]||0,y0=ax[1]||0,x1=ax[2]||0,y1=ax[3]||0;if(pressedButton(g,12)||y0<-.45)n.add('xu');if(pressedButton(g,15)||x0>.45)n.add('xr');if(pressedButton(g,13)||y0>.45)n.add('xd');if(pressedButton(g,14)||x0<-.45)n.add('xl');if(y1<-.45||pressedButton(g,7))n.add('yu');if(x1>.45||pressedButton(g,5))n.add('yr');if(y1>.45||pressedButton(g,6))n.add('yd');if(x1<-.45||pressedButton(g,4))n.add('yl');if(pressedButton(g,0))n.add('a');if(pressedButton(g,1))n.add('b');if(pressedButton(g,9))n.add('start');INPUT.replace('gamepad',n);if(APP.gamepadName!==g.id)updateGamepadStatus(g.id)}
function animate(t){requestAnimationFrame(animate);pollGamepad();let c=APP.core;if(!APP.rom||!c.running){APP.last=t;return}if(!APP.last)APP.last=t;let dt=Math.min(80,t-APP.last);APP.last=t;APP.acc+=dt*75.472*APP.speed/1000;let n=0,cap=APP.speed>=3?12:APP.speed>=2?9:6;while(APP.acc>=1&&n<cap&&c.running){INPUT.tick();c.runFrame();APP.acc--;n++}gifCaptureTick(t);APP.fpsFrames+=n;if(!APP.fpsTime)APP.fpsTime=t;if(t-APP.fpsTime>=500){APP.fps=APP.fpsFrames*1000/(t-APP.fpsTime);APP.fpsFrames=0;APP.fpsTime=t;updateStatus()}if((c.frameCount&63)===0)updateStatus()}
const TOUCH_VIS=new Map;function bindTouch(){$$('[data-key]').forEach(b=>{let k=b.dataset.key,src=e=>`touch:${e.pointerId}`,up=e=>{if(e)e.preventDefault();let v=TOUCH_VIS.get(e.pointerId);if(v)v.classList.remove('pressed');TOUCH_VIS.delete(e.pointerId);INPUT.clear(src(e))};b.addEventListener('pointerdown',e=>{e.preventDefault();try{b.setPointerCapture(e.pointerId)}catch(_){};b.classList.add('pressed');TOUCH_VIS.set(e.pointerId,b);INPUT.replace(src(e),new Set([k]));let h=+APP.settings.haptics;if(h&&navigator.vibrate)try{navigator.vibrate(h)}catch(_){}});b.addEventListener('pointermove',e=>{let id=src(e);if(!INPUT.sources.has(id))return;let hit=document.elementFromPoint(e.clientX,e.clientY)?.closest?.('[data-key]'),nk=hit?.dataset?.key,old=TOUCH_VIS.get(e.pointerId);if(old!==hit){if(old)old.classList.remove('pressed');if(hit)hit.classList.add('pressed');if(hit)TOUCH_VIS.set(e.pointerId,hit);else TOUCH_VIS.delete(e.pointerId)}INPUT.replace(id,nk?new Set([nk]):new Set)});b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up);b.addEventListener('contextmenu',e=>e.preventDefault())})}
function bindKeyboard(){const map={ArrowUp:'xu',ArrowRight:'xr',ArrowDown:'xd',ArrowLeft:'xl',w:'yu',d:'yr',s:'yd',a:'yl',z:'a',x:'b',c:'start'},hot={p:()=>takeScreenshot(),g:()=>toggleGifCapture(),m:()=>capturePngMssZip()};document.addEventListener('keydown',e=>{if(e.target&&e.target.matches?.('input,select,textarea'))return;let key=e.key?.length===1?e.key.toLowerCase():e.key,k=map[key];if(k){if(e.repeat)return;e.preventDefault();INPUT.set('keyboard',k,true);return}let h=hot[key];if(h&&!e.repeat){e.preventDefault();h()}});document.addEventListener('keyup',e=>{if(e.target&&e.target.matches?.('input,select,textarea'))return;let key=e.key?.length===1?e.key.toLowerCase():e.key,k=map[key];if(!k)return;e.preventDefault();INPUT.set('keyboard',k,false)})}
function bindSetting(id,key,kind='checked'){let e=$('#'+id);e.addEventListener('change',()=>{APP.settings[key]=kind==='value'?e.value:kind==='number'?+e.value:e.checked;storeSettings();applySettings()})}
